package com.neighbormarket.service;

import com.baomidou.mybatisplus.core.toolkit.Wrappers;
import com.neighbormarket.domain.*;
import com.neighbormarket.mapper.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.time.LocalDateTime;
import java.util.*;

@Service
public class ExchangeService {
 private final ItemMapper items; private final AppUserMapper users; private final PickupSlotMapper slots; private final ItemInterestMapper interests; private final HandoverMapper handovers; private final ItemCommentMapper comments;
 public ExchangeService(ItemMapper a,AppUserMapper b,PickupSlotMapper c,ItemInterestMapper d,HandoverMapper e,ItemCommentMapper f){items=a;users=b;slots=c;interests=d;handovers=e;comments=f;}
 private ResponseStatusException err(HttpStatus s,String m){return new ResponseStatusException(s,m);} private AppUser user(String name){AppUser u=users.selectOne(Wrappers.lambdaQuery(AppUser.class).eq(AppUser::getUsername,name));if(u==null)throw err(HttpStatus.UNAUTHORIZED,"请先登录");return u;} private Item item(Long id){Item i=items.selectById(id);if(i==null)throw err(HttpStatus.NOT_FOUND,"物品不存在");return i;}
 public List<SlotView> validSlots(Long itemId){LocalDateTime now=LocalDateTime.now();return slots.selectList(Wrappers.lambdaQuery(PickupSlot.class).eq(PickupSlot::getItemId,itemId).gt(PickupSlot::getStartAt,now).orderByAsc(PickupSlot::getStartAt)).stream().map(this::slotView).toList();}
 @Transactional public List<SlotView> configure(Long itemId,String location,List<SlotInput> input,String username){AppUser u=user(username);Item i=item(itemId);if(!i.getPublisherId().equals(u.getId()))throw err(HttpStatus.FORBIDDEN,"只有发布者可以设置交接信息");if(i.getStatus()!=ItemStatus.AVAILABLE)throw err(HttpStatus.CONFLICT,"待交接或已送出物品不能修改时段");if(location==null||location.isBlank()||location.trim().length()>200)throw err(HttpStatus.BAD_REQUEST,"请输入200字以内的公共交接地点");if(input==null||input.isEmpty()||input.size()>5)throw err(HttpStatus.BAD_REQUEST,"请提供1至5个交接时段");if(interests.selectCount(Wrappers.lambdaQuery(ItemInterest.class).eq(ItemInterest::getItemId,itemId).eq(ItemInterest::getStatus,InterestStatus.WAITING))>0)throw err(HttpStatus.CONFLICT,"已有等待意向，不能修改时段");LocalDateTime now=LocalDateTime.now();for(SlotInput x:input)validateSlot(x,now);slots.delete(Wrappers.lambdaQuery(PickupSlot.class).eq(PickupSlot::getItemId,itemId));i.setPickupLocation(location.trim());items.updateById(i);for(SlotInput x:input){PickupSlot s=new PickupSlot();s.setItemId(itemId);s.setStartAt(x.startAt());s.setEndAt(x.endAt());s.setCreatedAt(now);slots.insert(s);}return validSlots(itemId);}
 public void addInitialSlots(Item i,List<SlotInput> input){if(i.getPickupLocation()==null||i.getPickupLocation().isBlank())throw err(HttpStatus.BAD_REQUEST,"请输入公共交接地点");if(input==null||input.isEmpty()||input.size()>5)throw err(HttpStatus.BAD_REQUEST,"请提供1至5个交接时段");LocalDateTime now=LocalDateTime.now();for(SlotInput x:input){validateSlot(x,now);PickupSlot s=new PickupSlot();s.setItemId(i.getId());s.setStartAt(x.startAt());s.setEndAt(x.endAt());s.setCreatedAt(now);slots.insert(s);}}
 private void validateSlot(SlotInput x,LocalDateTime now){if(x==null||x.startAt()==null||x.endAt()==null)throw err(HttpStatus.BAD_REQUEST,"时段不能为空");if(!x.startAt().isAfter(now))throw err(HttpStatus.BAD_REQUEST,"时段必须尚未开始");if(!x.endAt().isAfter(x.startAt()))throw err(HttpStatus.BAD_REQUEST,"结束时间必须晚于开始时间");}
 @Transactional public InterestView want(Long itemId,Long slotId,String username){AppUser u=user(username);Item i=item(itemId);if(i.getPublisherId().equals(u.getId()))throw err(HttpStatus.FORBIDDEN,"不能想要自己发布的物品");if(i.getStatus()!=ItemStatus.AVAILABLE)throw err(HttpStatus.CONFLICT,"物品当前不可领取");PickupSlot s=slots.selectById(slotId);if(s==null||!s.getItemId().equals(itemId))throw err(HttpStatus.BAD_REQUEST,"时段不属于该物品");if(!s.getStartAt().isAfter(LocalDateTime.now()))throw err(HttpStatus.CONFLICT,"该时段已开始或过期");ItemInterest it=interests.selectOne(Wrappers.lambdaQuery(ItemInterest.class).eq(ItemInterest::getItemId,itemId).eq(ItemInterest::getUserId,u.getId()));LocalDateTime now=LocalDateTime.now();if(it==null){it=new ItemInterest();it.setItemId(itemId);it.setUserId(u.getId());it.setCreatedAt(now);}else if(it.getStatus()==InterestStatus.CONFIRMED)throw err(HttpStatus.CONFLICT,"该意向已被确认");it.setSlotId(slotId);it.setStatus(InterestStatus.WAITING);it.setUpdatedAt(now);if(it.getId()==null)interests.insert(it);else interests.updateById(it);return interestView(it);}
 @Transactional public InterestView cancelInterest(Long itemId,String username){AppUser u=user(username);ItemInterest it=interests.selectOne(Wrappers.lambdaQuery(ItemInterest.class).eq(ItemInterest::getItemId,itemId).eq(ItemInterest::getUserId,u.getId()));if(it==null)throw err(HttpStatus.NOT_FOUND,"意向不存在");if(it.getStatus()!=InterestStatus.WAITING)throw err(HttpStatus.CONFLICT,"只有等待中的意向可以取消");it.setStatus(InterestStatus.CANCELLED);it.setUpdatedAt(LocalDateTime.now());interests.updateById(it);return interestView(it);}
 public List<InterestView> itemInterests(Long itemId,String username){AppUser u=user(username);Item i=item(itemId);if(!i.getPublisherId().equals(u.getId()))throw err(HttpStatus.FORBIDDEN,"只有发布者可以查看完整意向名单");return interests.selectList(Wrappers.lambdaQuery(ItemInterest.class).eq(ItemInterest::getItemId,itemId).orderByDesc(ItemInterest::getUpdatedAt)).stream().map(this::interestView).toList();}
 public InterestView myInterest(Long itemId,String username){AppUser u=user(username);ItemInterest it=interests.selectOne(Wrappers.lambdaQuery(ItemInterest.class).eq(ItemInterest::getItemId,itemId).eq(ItemInterest::getUserId,u.getId()));return it==null?null:interestView(it);}
 @Transactional public HandoverView confirm(Long interestId,String username){AppUser publisher=user(username);ItemInterest it=interests.selectById(interestId);if(it==null)throw err(HttpStatus.NOT_FOUND,"意向不存在");Item i=item(it.getItemId());if(!i.getPublisherId().equals(publisher.getId()))throw err(HttpStatus.FORBIDDEN,"只有发布者可以确认领取人");if(it.getStatus()!=InterestStatus.WAITING)throw err(HttpStatus.CONFLICT,"意向已不是等待状态");PickupSlot s=slots.selectById(it.getSlotId());if(s==null||!s.getItemId().equals(i.getId())||!s.getStartAt().isAfter(LocalDateTime.now()))throw err(HttpStatus.CONFLICT,"交接时段已失效");if(i.getPickupLocation()==null||i.getPickupLocation().isBlank())throw err(HttpStatus.CONFLICT,"请先设置交接地点");int won=items.update(null,Wrappers.lambdaUpdate(Item.class).eq(Item::getId,i.getId()).eq(Item::getStatus,ItemStatus.AVAILABLE).isNull(Item::getCurrentHandoverId).set(Item::getStatus,ItemStatus.RESERVED));if(won!=1)throw err(HttpStatus.CONFLICT,"物品已由另一请求确认，请刷新");LocalDateTime now=LocalDateTime.now();Handover h=new Handover();h.setItemId(i.getId());h.setPublisherId(publisher.getId());h.setRecipientId(it.getUserId());h.setInterestId(it.getId());h.setStartAt(s.getStartAt());h.setEndAt(s.getEndAt());h.setLocationSnapshot(i.getPickupLocation());h.setStatus(HandoverStatus.ACTIVE);h.setCreatedAt(now);handovers.insert(h);items.update(null,Wrappers.lambdaUpdate(Item.class).eq(Item::getId,i.getId()).eq(Item::getStatus,ItemStatus.RESERVED).isNull(Item::getCurrentHandoverId).set(Item::getCurrentHandoverId,h.getId()));it.setStatus(InterestStatus.CONFIRMED);it.setUpdatedAt(now);interests.updateById(it);return handoverView(h);}
 public List<HandoverView> myHandovers(String username){AppUser u=user(username);return handovers.selectList(Wrappers.lambdaQuery(Handover.class).and(q->q.eq(Handover::getPublisherId,u.getId()).or().eq(Handover::getRecipientId,u.getId())).orderByDesc(Handover::getCreatedAt)).stream().map(this::handoverView).toList();}
 public HandoverView handover(Long id,String username){AppUser u=user(username);Handover h=handovers.selectById(id);if(h==null)throw err(HttpStatus.NOT_FOUND,"交接不存在");if(!h.getPublisherId().equals(u.getId())&&!h.getRecipientId().equals(u.getId()))throw err(HttpStatus.FORBIDDEN,"只有交接双方可以查看");return handoverView(h);}
 @Transactional public HandoverView cancelHandover(Long id,String username){AppUser u=user(username);Handover h=handovers.selectById(id);if(h==null)throw err(HttpStatus.NOT_FOUND,"交接不存在");if(!h.getPublisherId().equals(u.getId())&&!h.getRecipientId().equals(u.getId()))throw err(HttpStatus.FORBIDDEN,"只有交接双方可以取消");if(h.getStatus()!=HandoverStatus.ACTIVE)throw err(HttpStatus.CONFLICT,"该交接已结束，不能重复取消");LocalDateTime now=LocalDateTime.now();int changed=handovers.update(null,Wrappers.lambdaUpdate(Handover.class).eq(Handover::getId,id).eq(Handover::getStatus,HandoverStatus.ACTIVE).set(Handover::getStatus,HandoverStatus.CANCELLED).set(Handover::getCancelledAt,now));if(changed!=1)throw err(HttpStatus.CONFLICT,"交接状态已变化");int restored=items.update(null,Wrappers.lambdaUpdate(Item.class).eq(Item::getId,h.getItemId()).eq(Item::getStatus,ItemStatus.RESERVED).eq(Item::getCurrentHandoverId,id).set(Item::getStatus,ItemStatus.AVAILABLE).set(Item::getCurrentHandoverId,null));if(restored!=1)throw err(HttpStatus.CONFLICT,"物品状态与交接不一致");interests.update(null,Wrappers.lambdaUpdate(ItemInterest.class).eq(ItemInterest::getId,h.getInterestId()).eq(ItemInterest::getStatus,InterestStatus.CONFIRMED).set(ItemInterest::getStatus,InterestStatus.CANCELLED).set(ItemInterest::getUpdatedAt,now));return handoverView(handovers.selectById(id));}
 @Transactional public HandoverView complete(Long id,String username){AppUser u=user(username);Handover h=handovers.selectById(id);if(h==null)throw err(HttpStatus.NOT_FOUND,"交接不存在");if(!h.getPublisherId().equals(u.getId()))throw err(HttpStatus.FORBIDDEN,"只有发布者可以标记已送出");if(h.getStatus()!=HandoverStatus.ACTIVE)throw err(HttpStatus.CONFLICT,"该交接已结束，不能重复完成");LocalDateTime now=LocalDateTime.now();int changed=handovers.update(null,Wrappers.lambdaUpdate(Handover.class).eq(Handover::getId,id).eq(Handover::getStatus,HandoverStatus.ACTIVE).set(Handover::getStatus,HandoverStatus.COMPLETED).set(Handover::getCompletedAt,now));if(changed!=1)throw err(HttpStatus.CONFLICT,"交接状态已变化");int done=items.update(null,Wrappers.lambdaUpdate(Item.class).eq(Item::getId,h.getItemId()).eq(Item::getStatus,ItemStatus.RESERVED).eq(Item::getCurrentHandoverId,id).set(Item::getStatus,ItemStatus.COMPLETED).set(Item::getCompletedAt,now));if(done!=1)throw err(HttpStatus.CONFLICT,"物品状态与交接不一致");return handoverView(handovers.selectById(id));}
 public List<CommentView> comments(Long itemId){item(itemId);return comments.selectList(Wrappers.lambdaQuery(ItemComment.class).eq(ItemComment::getItemId,itemId).orderByAsc(ItemComment::getCreatedAt)).stream().map(this::commentView).toList();}
 @Transactional public CommentView comment(Long itemId,String content,String username){AppUser u=user(username);Item i=item(itemId);if(i.getStatus()==ItemStatus.COMPLETED)throw err(HttpStatus.CONFLICT,"已送出物品的留言只读");String text=validatedComment(content);ItemComment c=new ItemComment();c.setItemId(itemId);c.setUserId(u.getId());c.setParentId(null);c.setContent(text);c.setCreatedAt(LocalDateTime.now());comments.insert(c);return commentView(c);}
 @Transactional public CommentView reply(Long itemId,Long parentId,String content,String username){AppUser u=user(username);Item i=item(itemId);if(i.getStatus()==ItemStatus.COMPLETED)throw err(HttpStatus.CONFLICT,"已送出物品的留言只读");if(!i.getPublisherId().equals(u.getId()))throw err(HttpStatus.FORBIDDEN,"只有物品发布者可以回复");ItemComment parent=comments.selectById(parentId);if(parent==null)throw err(HttpStatus.NOT_FOUND,"留言不存在");if(!parent.getItemId().equals(itemId))throw err(HttpStatus.BAD_REQUEST,"留言不属于该物品");if(parent.getParentId()!=null)throw err(HttpStatus.BAD_REQUEST,"只能回复顶层留言");ItemComment c=new ItemComment();c.setItemId(itemId);c.setUserId(u.getId());c.setParentId(parentId);c.setContent(validatedComment(content));c.setCreatedAt(LocalDateTime.now());comments.insert(c);return commentView(c);}
 private String validatedComment(String content){String text=content==null?"":content.trim();if(text.isEmpty()||text.length()>500)throw err(HttpStatus.BAD_REQUEST,"留言须为1至500字");return text;}
 public Dashboard dashboard(String username){AppUser u=user(username);List<InterestView> mine=interests.selectList(Wrappers.lambdaQuery(ItemInterest.class).eq(ItemInterest::getUserId,u.getId()).orderByDesc(ItemInterest::getUpdatedAt)).stream().map(this::interestView).toList();return new Dashboard(mine,myHandovers(username));}
 private SlotView slotView(PickupSlot s){return new SlotView(s.getId(),s.getItemId(),s.getStartAt(),s.getEndAt());}
 private InterestView interestView(ItemInterest i){AppUser u=users.selectById(i.getUserId());PickupSlot s=slots.selectById(i.getSlotId());Item x=items.selectById(i.getItemId());return new InterestView(i.getId(),i.getItemId(),x==null?"":x.getTitle(),i.getUserId(),u==null?"":u.getNickname(),i.getSlotId(),s==null?null:s.getStartAt(),s==null?null:s.getEndAt(),i.getStatus(),i.getUpdatedAt());}
 private HandoverView handoverView(Handover h){Item i=items.selectById(h.getItemId());AppUser p=users.selectById(h.getPublisherId()),r=users.selectById(h.getRecipientId());return new HandoverView(h.getId(),h.getItemId(),i==null?"":i.getTitle(),h.getPublisherId(),p==null?"":p.getNickname(),h.getRecipientId(),r==null?"":r.getNickname(),h.getStartAt(),h.getEndAt(),h.getLocationSnapshot(),h.getStatus(),h.getCreatedAt(),h.getCancelledAt(),h.getCompletedAt());}
 private CommentView commentView(ItemComment c){AppUser u=users.selectById(c.getUserId());return new CommentView(c.getId(),c.getItemId(),c.getUserId(),u==null?"":u.getNickname(),c.getParentId(),c.getContent(),c.getCreatedAt());}
 public record SlotInput(LocalDateTime startAt,LocalDateTime endAt){} public record SlotView(Long id,Long itemId,LocalDateTime startAt,LocalDateTime endAt){} public record InterestView(Long id,Long itemId,String itemTitle,Long userId,String nickname,Long slotId,LocalDateTime startAt,LocalDateTime endAt,InterestStatus status,LocalDateTime updatedAt){} public record HandoverView(Long id,Long itemId,String itemTitle,Long publisherId,String publisherName,Long recipientId,String recipientName,LocalDateTime startAt,LocalDateTime endAt,String location,HandoverStatus status,LocalDateTime createdAt,LocalDateTime cancelledAt,LocalDateTime completedAt){} public record CommentView(Long id,Long itemId,Long userId,String nickname,Long parentId,String content,LocalDateTime createdAt){} public record Dashboard(List<InterestView> interests,List<HandoverView> handovers){}
}